/* Shale.glob!: Str => List(Str) */
extern RocList shale_glob(RocStr arg0);

/* Shale.grep_all!: Str, Str => List({ line : U64, text : Str }) */
extern RocList shale_grep_all(RocStr arg0, RocStr arg1);

/* Shale.list!: Str => [Found(List(Str)), Missing] */
extern FoundOrMissingType7 shale_list(RocStr arg0);

/* Shale.print!: Str => {} */
extern void shale_print(RocStr arg0);

/* Shale.read!: Str => [Found(Str), Missing] */
extern FoundOrMissingType8 shale_read(RocStr arg0);

/* Shale.run!: { argv : List(Str), keep : [Head(U64), Tail(U64), Whole(U64)], timeout_ms : U64, want : Str } => { code : I64, out : Str } */
extern AnonStruct1763995a077e9c1f shale_run(ShaleRunArgs arg0);

/* Shale.write!: Str, Str => {} */
extern void shale_write(RocStr arg0, RocStr arg1);


// Provided Symbols

/* Entrypoint: main_for_host! */
extern void roc_main(void);


// HostedFunctions Registry

/**
 * Registry of all hosted function implementations.
 * Store each implementation cast to HostedFn.
 */
typedef struct {
    HostedFn shale_arg_bang;  /* index 0, C name: shale_arg */
    HostedFn shale_exists_bang;  /* index 1, C name: shale_exists */
    HostedFn shale_fail_bang;  /* index 2, C name: shale_fail */
    HostedFn shale_glob_bang;  /* index 3, C name: shale_glob */
    HostedFn shale_grep_all_bang;  /* index 4, C name: shale_grep_all */
    HostedFn shale_list_bang;  /* index 5, C name: shale_list */
    HostedFn shale_print_bang;  /* index 6, C name: shale_print */
    HostedFn shale_read_bang;  /* index 7, C name: shale_read */
    HostedFn shale_run_bang;  /* index 8, C name: shale_run */
    HostedFn shale_write_bang;  /* index 9, C name: shale_write */
} HostedFunctions;


